"use client";

import { useState } from "react";
import {
  AnnouncementBar,
  BenefitsStrip,
  Categories,
  Footer,
  Header,
  Hero,
  OfferBanner,
  ProductSection,
  PromoBanners,
  Testimonials,
} from "../components/home";
import { bestSellers, newArrivals } from "../data/home-data";

export function MarketplaceHomePage() {
  const [cartCount, setCartCount] = useState(0);
  const addToCart = () => setCartCount((value) => value + 1);

  return (
    <div className="min-w-0 bg-[var(--color-fondo)] text-[var(--color-texto)]">
      <AnnouncementBar />
      <Header cartCount={cartCount} />
      <main>
        <Hero />
        <OfferBanner />
        <Categories />
        <ProductSection
          title="Más vendidos"
          products={bestSellers}
          onAdd={addToCart}
        />
        <ProductSection
          title="Nuevas llegadas"
          products={newArrivals}
          isNew
          onAdd={addToCart}
        />
        <PromoBanners />
        <Testimonials />
        <BenefitsStrip />
      </main>
      <Footer />
    </div>
  );
}